import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** Opens and initializes the SQLite database shared by the server and worker. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL,
      steps INTEGER NOT NULL, fail_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
      completed INTEGER NOT NULL DEFAULT 0, result TEXT, error TEXT,
      created_at TEXT NOT NULL, updated_at TEXT NOT NULL, available_at INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS jobs_status_available ON jobs(status, available_at, created_at);
    CREATE TABLE IF NOT EXISTS idempotency (
      key TEXT PRIMARY KEY, payload TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES jobs(id)
    );
    CREATE TABLE IF NOT EXISTS worker_heartbeat (id INTEGER PRIMARY KEY CHECK(id = 1), seen_at INTEGER NOT NULL);
  `);
  return db;
}

export function toJob(row: Record<string, unknown>): Job {
  return {
    id: String(row.id), status: row.status as JobStatus, input: String(row.input),
    steps: Number(row.steps), failAttempts: Number(row.fail_attempts), attempts: Number(row.attempts),
    progress: { completed: Number(row.completed), total: Number(row.steps) },
    result: row.result === null ? null : JSON.parse(String(row.result)) as { output: string },
    error: row.error === null ? null : String(row.error),
    createdAt: String(row.created_at), updatedAt: String(row.updated_at),
  };
}

export const JOB_COLUMNS = 'id, status, input, steps, fail_attempts, attempts, completed, result, error, created_at, updated_at';
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, JOB_COLUMNS } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
type FieldError = { field: string; message: string };

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function readBody(req: IncomingMessage): Promise<string> {
  let text = '';
  for await (const chunk of req) {
    text += Buffer.isBuffer(chunk) ? chunk.toString('utf8') : String(chunk);
    if (text.length > 1_000_000) throw new Error('too_large');
  }
  return text;
}

const server = createServer(async (req, res) => {
  const pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
  if (pathname === '/' && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const row = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id = 1').get() as { seen_at?: number } | undefined;
    return send(res, 200, { status: 'ok', worker: row && Date.now() - Number(row.seen_at) <= 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'GET') {
      const rows = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs ORDER BY created_at DESC, rowid DESC`).all() as Record<string, unknown>[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    if (req.method !== 'POST') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const contentType = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) {
      return error(res, 400, 'invalid_request', 'Request must use application/json.', [{ field: 'body', message: 'Content-Type must be application/json.' }]);
    }
    let parsed: unknown;
    try { parsed = JSON.parse(await readBody(req)); }
    catch { return error(res, 400, 'invalid_request', 'Request body must be valid JSON.', [{ field: 'body', message: 'Must be valid JSON.' }]); }
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return error(res, 400, 'invalid_request', 'Request body must be an object.', [{ field: 'body', message: 'Must be a JSON object.' }]);
    }
    const data = parsed as Record<string, unknown>;
    const fields: FieldError[] = [];
    for (const key of Object.keys(data)) if (!['input', 'steps', 'failAttempts'].includes(key)) fields.push({ field: key, message: 'Unknown field.' });
    if (!Object.hasOwn(data, 'input')) fields.push({ field: 'input', message: 'Required.' });
    else if (typeof data.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
    else if (data.input.length < 1 || data.input.length > 1000 || data.input.trim().length === 0) fields.push({ field: 'input', message: 'Must contain 1–1000 characters and not be only whitespace.' });
    const steps = Object.hasOwn(data, 'steps') ? data.steps : 5;
    const failAttempts = Object.hasOwn(data, 'failAttempts') ? data.failAttempts : 0;
    if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
    if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
    const key = req.headers['idempotency-key'];
    if (key !== undefined && (Array.isArray(key) || !/^[A-Za-z0-9_-]{1,128}$/.test(key))) fields.push({ field: 'Idempotency-Key', message: 'Must contain 1–128 letters, digits, underscores, or hyphens.' });
    if (fields.length) return error(res, 400, 'invalid_request', 'Request validation failed.', fields);
    const idempotencyKey = typeof key === 'string' ? key : undefined;

    const input = data.input as string;
    const normalized = { input, steps: steps as number, failAttempts: failAttempts as number };
    const payload = JSON.stringify(normalized);
    try {
      db.exec('BEGIN IMMEDIATE');
      if (idempotencyKey !== undefined) {
        const existing = db.prepare('SELECT i.payload, j.* FROM idempotency i JOIN jobs j ON j.id = i.job_id WHERE i.key = ?').get(idempotencyKey) as Record<string, unknown> | undefined;
        if (existing) {
          db.exec('COMMIT');
          if (existing.payload !== payload) return error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
          return send(res, 200, toJob(existing));
        }
      }
      const now = new Date().toISOString();
      const id = randomUUID();
      db.prepare(`INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,completed,result,error,created_at,updated_at,available_at)
        VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, 0)`).run(id, input, normalized.steps, normalized.failAttempts, now, now);
      if (idempotencyKey !== undefined) db.prepare('INSERT INTO idempotency (key,payload,job_id) VALUES (?,?,?)').run(idempotencyKey, payload, id);
      const row = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`).get(id) as Record<string, unknown>;
      db.exec('COMMIT');
      return send(res, 201, toJob(row));
    } catch (e) {
      try { db.exec('ROLLBACK'); } catch { /* transaction already closed */ }
      console.error('request failed', e);
      return error(res, 500, 'internal_error', 'The request could not be completed.');
    }
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    let id: string;
    try { id = decodeURIComponent(match[1]!); } catch { return error(res, 404, 'not_found', 'Job not found.'); }
    const row = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`).get(id) as Record<string, unknown> | undefined;
    if (!row) return error(res, 404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  if (pathname.startsWith('/api/')) return error(res, 404, 'not_found', 'Route not found.');
  error(res, 404, 'not_found', 'Route not found.');
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
function shutdown(): void {
  server.close(() => { db.close(); process.exit(0); });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, JOB_COLUMNS, toJob } from './db.ts';

const db = openDatabase();
let stopping = false;
let activeId: string | null = null;

// A running row left by a killed worker is eligible for a fresh attempt.
db.prepare("UPDATE jobs SET status='queued', completed=0, updated_at=?, available_at=0 WHERE status='running'").run(new Date().toISOString());
const heartbeat = (): void => {
  db.prepare('INSERT INTO worker_heartbeat (id,seen_at) VALUES (1,?) ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at').run(Date.now());
};
heartbeat();
const heartbeatTimer = setInterval(heartbeat, 750);

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => { stopping = true; });
}
console.log('worker started');

try {
  while (!stopping) {
    let job;
    db.exec('BEGIN IMMEDIATE');
    try {
      const row = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE status='queued' AND available_at <= ? ORDER BY created_at ASC, rowid ASC LIMIT 1`).get(Date.now()) as Record<string, unknown> | undefined;
      if (row) {
        const rowId = String(row.id);
        const now = new Date().toISOString();
        db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, completed=0, result=NULL, error=NULL, updated_at=? WHERE id=? AND status='queued'").run(now, rowId);
        job = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id=?`).get(rowId) as Record<string, unknown>;
      }
      db.exec('COMMIT');
    } catch (e) {
      try { db.exec('ROLLBACK'); } catch { /* transaction already closed */ }
      throw e;
    }
    if (!job) { await sleep(100); continue; }
    const current = toJob(job);
    activeId = current.id;
    try {
      const attempt = current.attempts;
      if (attempt <= current.failAttempts) {
        await sleep(100);
        if (stopping) break;
        if (attempt >= 3) {
          db.prepare("UPDATE jobs SET status='failed', completed=0, result=NULL, error='transient failure', updated_at=? WHERE id=? AND status='running'").run(new Date().toISOString(), current.id);
        } else {
          db.prepare("UPDATE jobs SET status='queued', completed=0, result=NULL, error=NULL, available_at=?, updated_at=? WHERE id=? AND status='running'").run(Date.now() + 500, new Date().toISOString(), current.id);
        }
        activeId = null;
        continue;
      }
      for (let step = 1; step <= current.steps; step++) {
        await sleep(100);
        if (stopping) break;
        db.prepare("UPDATE jobs SET completed=?, updated_at=? WHERE id=? AND status='running'").run(step, new Date().toISOString(), current.id);
      }
      if (stopping) break;
      db.prepare("UPDATE jobs SET status='completed', completed=steps, result=?, error=NULL, updated_at=? WHERE id=? AND status='running'").run(JSON.stringify({ output: current.input.toUpperCase() }), new Date().toISOString(), current.id);
      activeId = null;
    } catch (e) {
      activeId = null;
      throw e;
    }
  }
} finally {
  clearInterval(heartbeatTimer);
  if (activeId) db.prepare("UPDATE jobs SET status='queued', completed=0, available_at=0, updated_at=? WHERE id=? AND status='running'").run(new Date().toISOString(), activeId);
  db.close();
}
