  <title>Job tracker</title>
  <style>
    body { max-width: 760px; margin: 2rem auto; padding: 0 1rem; font: 16px/1.5 system-ui, sans-serif; color: #20242a; }
    form { display: grid; gap: .8rem; max-width: 480px; margin: 1.5rem 0; }
    label { display: grid; gap: .25rem; }
    input, button { font: inherit; padding: .5rem; }
    button { justify-self: start; cursor: pointer; }
    [role="alert"] { color: #a21b1b; min-height: 1.5em; }
    #job-list { list-style: none; padding: 0; }
    [data-testid="job-item"] { border: 1px solid #d4d8dd; border-radius: 6px; padding: .8rem; margin: .6rem 0; }
    .meta { color: #545b64; font-size: .9rem; }
  </style>
</head>
<body>
  <h1>Job tracker</h1>
  <form data-testid="job-form">
    <label>Input <input data-testid="job-input" name="input" type="text" maxlength="1000"></label>
    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" value="5"></label>
    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0"></label>
    <button data-testid="job-submit" type="submit">Submit job</button>
  </form>
  <div data-testid="form-error" role="alert" aria-live="polite"></div>
  <h2>Jobs</h2>
  <ul data-testid="job-list"></ul>
  <script>
    const form = document.querySelector('[data-testid="job-form"]');
    const errorBox = document.querySelector('[data-testid="form-error"]');
    const list = document.querySelector('[data-testid="job-list"]');
    const showError = (message) => { errorBox.textContent = message; };

    function render(jobs) {
      list.replaceChildren();
      for (const job of jobs) {
        const item = document.createElement('li');
        item.dataset-testid = 'job-item';
        item.dataset.jobId = job.id;
        const title = document.createElement('strong');
        title.textContent = job.input;
        const status = document.createElement('span');
        status.dataset.testid = 'job-status';
        status.textContent = job.status;
        const progress = document.createElement('span');
        progress.dataset.testid = 'job-progress';
        progress.textContent = `${job.progress.completed}/${job.progress.total}`;
        const result = document.createElement('div');
        result.dataset.testid = 'job-result';
        result.textContent = job.result ? job.result.output : (job.error || '');
        const meta = document.createElement('div');
        meta.className = 'meta';
        meta.append('Status: ', status, ' · Progress: ', progress);
        item.append(title, meta, result);
        list.append(item);
      }
    }

    async function refresh() {
      try {
        const response = await fetch('/api/jobs');
        if (response.ok) render((await response.json()).jobs);
      } catch { /* the next poll retries */ }
    }

    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      showError('');
      const data = new FormData(form);
      const payload = {
        input: data.get('input'),
        steps: Number(data.get('steps')),
        failAttempts: Number(data.get('failAttempts'))
      };
      try {
        const response = await fetch('/api/jobs', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload)
        });
        const body = await response.json();
        if (!response.ok) {
          const fields = body.error?.fields || [];
          showError(fields.length ? `${body.error.message} ${fields.map((f) => `${f.field}: ${f.message}`).join(' ')}` : (body.error?.message || 'Submission failed.'));
          return;
        }
        form.elements.input.value = '';
        await refresh();
      } catch { showError('Could not submit the job. Please try again.'); }
    });
    refresh();
    setInterval(refresh, 700);
  </script>
</body>
</html>
